from fractions import Fraction
def ref(z,s):
    q=Fraction(z,1)/(2**s)
    neg = q<0
    aq = -q if neg else q
    fl = aq.numerator//aq.denominator
    rem = aq-fl
    r = fl+1 if rem>=Fraction(1,2) else fl
    return -r if neg else r
def mine(z,s):
    if s==0: return z
    d=1<<s; h=d>>1
    if z>=0: return (z+h)//d
    return -((-z+h)//d)
bad=0; n=0
for s in range(0,17):
    for z in list(range(-4000,4001)):
        n+=1
        if ref(z,s)!=mine(z,s):
            bad+=1
            if bad<10: print('DIFF',z,s,ref(z,s),mine(z,s))
    # extremes
    for z in [-(2**31)-5, -(2**31), 2**31-1, 10**12, -10**12, -1, 1]:
        n+=1
        if ref(z,s)!=mine(z,s): bad+=1; print('DIFF ext',z,s)
print('checked',n,'diffs',bad)
EOF
